xpath.script:
(function () {
    var BUILTIN_CLASSES = {
        dark: 'ewseta-dark-mode',
        blue: 'ewseta-blue-mode',
        green: 'ewseta-green-mode',
        orange: 'ewseta-orange-mode',
    };
    var THEME_CLASSES = [
        'ewseta-dark-mode',
        'ewseta-blue-mode',
        'ewseta-green-mode',
        'ewseta-orange-mode',
        'ewseta-custom-mode',
    ];
    var CSS_VARS = [
        '--ewseta-dm-bg',
        '--ewseta-dm-bg-elevated',
        '--ewseta-dm-bg-subtle',
        '--ewseta-dm-bg-deep',
        '--ewseta-dm-text',
        '--ewseta-dm-text-muted',
        '--ewseta-dm-border',
        '--ewseta-dm-shadow',
        '--ewseta-voice-gradient-start',
        '--ewseta-body-gradient',
    ];

    function clearThemeState(html) {
        html.classList.remove.apply(html.classList, THEME_CLASSES);
        CSS_VARS.forEach(function (key) {
            html.style.removeProperty(key);
        });
        html.style.removeProperty('color-scheme');
    }

    function applyTheme(theme, config) {
        var html = document.documentElement;
        var themes = config.themes || ['light'];
        var resolved = themes.indexOf(theme) >= 0 ? theme : (config.defaultTheme || 'light');
        var meta = (config.themeMeta && config.themeMeta[resolved]) || {};
        clearThemeState(html);
        if (resolved === 'light') {
            // Base stylesheet.
        } else if (meta.type === 'custom' && meta.cssVars) {
            html.classList.add('ewseta-custom-mode');
            html.style.colorScheme = 'dark';
            Object.keys(meta.cssVars).forEach(function (key) {
                html.style.setProperty(key, meta.cssVars[key]);
            });
        } else if (BUILTIN_CLASSES[resolved]) {
            html.classList.add(BUILTIN_CLASSES[resolved]);
        }
        html.dataset.ewsetaTheme = resolved;
    }

    try {
        var config = ;
        window.ewsetaThemeConfig = config;
        var theme = config.defaultTheme || 'light';
        if (config.rememberUserChoice) {
            var stored = localStorage.getItem('ewseta-theme');
            if (stored && config.themes.indexOf(stored) >= 0) {
                theme = stored;
            }
        }
        applyTheme(theme, config);
    } catch (e) {}
})();
